import heapq


def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    k = len(prices)
    m = 1 << k
    adj: list[list[tuple[int, int, int]]] = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        adj[u].append((v, cost, zone))
        adj[v].append((u, cost, zone))

    station_mask = [0] * n
    for stop, z in stations:
        station_mask[stop] |= 1 << z

    avail: list[list[tuple[int, int]]] = [[] for _ in range(n)]
    for u in range(n):
        sm = station_mask[u]
        if sm:
            for z in range(k):
                if (sm >> z) & 1:
                    avail[u].append((1 << z, prices[z]))

    inf = 10**18
    dist = [inf] * (n * m)
    dist[0] = 0
    pq: list[tuple[int, int]] = [(0, 0)]
    target = n - 1

    while pq:
        d, state = heapq.heappop(pq)
        if d != dist[state]:
            continue
        u = state >> k
        if u == target:
            return d
        mask = state & (m - 1)

        for v, cost, zone in adj[u]:
            nd = d if (zone != -1 and ((mask >> zone) & 1)) else d + cost
            nstate = (v << k) | mask
            if nd < dist[nstate]:
                dist[nstate] = nd
                heapq.heappush(pq, (nd, nstate))

        for bit, price in avail[u]:
            if not (mask & bit):
                nd = d + price
                nstate = (u << k) | (mask | bit)
                if nd < dist[nstate]:
                    dist[nstate] = nd
                    heapq.heappush(pq, (nd, nstate))

    return -1
